const b = $json.body || $json;
const blocks = [];
for (const f of (b.archivos || []).slice(0, 10)) {
  if (f.tipo === 'pdf') blocks.push({ type: 'document', source: { type: 'url', url: f.url } });
  else if (f.tipo === 'imagen') blocks.push({ type: 'image', source: { type: 'url', url: f.url } });
  else if (f.tipo === 'texto') blocks.push({ type: 'text', text: 'Texto de la página de la carta:\n' + String(f.texto || '').slice(0, 60000) });
}
blocks.push({ type: 'text', text: 'Lee esta carta de restaurante y devuelve SOLO el JSON pedido.' });
const system = [
  'Eres un lector de cartas de restaurante. Devuelve únicamente un objeto JSON válido, sin texto antes ni después, con esta forma exacta:',
  '{"categorias":[{"nombre":"","subcategorias":[{"nombre":""}]}],"platos":[{"categoria":"","subcategoria":"","nombre":"","descripcion":"","precio":0,"opciones":""}]}',
  'Reglas: copia nombres y descripciones tal como aparecen (no inventes platos, precios ni descripciones). precio es un número en pesos sin símbolos ni separadores (12.500 -> 12500); si un plato no tiene precio, null. Si no hay subcategoría, usa "". opciones: tamaños, acompañantes o términos que la carta ofrezca para ese plato, separados por coma, o "". Si un plato tiene varios tamaños con precios distintos, crea un plato por tamaño ("Limonada 12 oz").'
].join('\n');
return [{ json: { job_id: b.job_id, company_id: b.company_id, callback_url: b.callback_url,
  request: { model: 'claude-sonnet-5-5', max_tokens: 8000, output_config: { effort: 'low' }, system, messages: [{ role: 'user', content: blocks }] } } }];

const meta = $('Armar mensaje').first().json;
const r = $json || {};
const out = { job_id: meta.job_id, company_id: meta.company_id };
if (r.error || !Array.isArray(r.content)) {
  out.error = 'Claude no respondió: ' + String((r.error && (r.error.message || r.error)) || 'sin contenido').slice(0, 300);
  return [{ json: { ...out, callback_url: meta.callback_url } }];
}
if (r.stop_reason === 'refusal') { out.error = 'Claude no pudo leer esta carta.'; return [{ json: { ...out, callback_url: meta.callback_url } }]; }
const text = r.content.filter((b) => b.type === 'text').map((b) => b.text).join('\n').trim();
const raw = text.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
const start = raw.indexOf('{'); const end = raw.lastIndexOf('}');
try {
  const data = JSON.parse(raw.slice(start, end + 1));
  const named = (x) => x && String(x.nombre || '').trim();
  out.categorias = (Array.isArray(data.categorias) ? data.categorias : []).filter(named).map((c) => ({ ...c, subcategorias: (c.subcategorias || []).filter(named) }));
  out.platos = (Array.isArray(data.platos) ? data.platos : []).filter(named);
  out.uso = r.usage || {};
} catch (e) {
  out.error = 'La respuesta no era JSON válido.';
}
return [{ json: { ...out, callback_url: meta.callback_url } }];
